import{_ as a,o as t,c as i,a2 as n}from"./chunks/framework.C-si7TFR.js";const h=JSON.parse('{"title":"Conditional Judgment","description":"Conditional branching in workflows, also known as decision logic, implements IF-ELSE functionality that enables workflows to automatically select different execution paths based on specified conditions. This feature supports dynamic decision-making using variable expressions.","frontmatter":{"title":"Conditional Judgment","description":"Conditional branching in workflows, also known as decision logic, implements IF-ELSE functionality that enables workflows to automatically select different execution paths based on specified conditions. This feature supports dynamic decision-making using variable expressions.","meta":[{"name":"keywords","content":"Conditional Judgment, IF-ELSE, Branch Logic, Exclusive Gateway, Low-code, AI Workflow, Process Engine"}]},"headers":[],"relativePath":"if.md","filePath":"if.md"}'),o={name:"if.md"};function r(l,e,s,c,d,u){return t(),i("div",null,[...e[0]||(e[0]=[n('<h2 id="conditional-judgment" tabindex="-1">Conditional Judgment <a class="header-anchor" href="#conditional-judgment" aria-label="Permalink to &quot;Conditional Judgment&quot;">​</a></h2><p>Determine the output as true or false based on the input and select the corresponding branch for execution. Supports the use of &quot;and&quot; and &quot;or&quot; to combine conditions, and allows for the use of variable expressions to make dynamic decisions at runtime.</p><blockquote><p>Historical interface images are withheld pending review and recapture. Check operations against the current interface.</p></blockquote><h2 id="input" tabindex="-1">Input <a class="header-anchor" href="#input" aria-label="Permalink to &quot;Input&quot;">​</a></h2><h3 id="conditional-relationships" tabindex="-1">Conditional Relationships <a class="header-anchor" href="#conditional-relationships" aria-label="Permalink to &quot;Conditional Relationships&quot;">​</a></h3><p>Complex conditional combinations can be formed using &quot;and&quot; and &quot;or&quot; relationships. If both &quot;and&quot; and &quot;or&quot; appear in a combination, the relationship is as follows: <code>CondX and CondY or CondZ...</code></p><ul><li><p><strong>And</strong></p><p>Returns true only if all conditions (Condition 1, Condition 2, ... Condition N) are true; otherwise, it returns false.</p></li><li><p><strong>Or</strong></p><p>Returns true if any one of the conditions is true; otherwise, it returns false if all conditions are false.</p></li></ul><h3 id="conditional-value-types" tabindex="-1">Conditional Value Types <a class="header-anchor" href="#conditional-value-types" aria-label="Permalink to &quot;Conditional Value Types&quot;">​</a></h3><p>Currently, the following four types of value comparisons are supported: boolean, date and time, numeric, and string.</p><blockquote><p>Historical interface images are withheld pending review and recapture. Check operations against the current interface.</p></blockquote><p>Values 1 and 2 can be constants or variable expressions (dynamically retrieved at runtime).</p><h4 id="boolean-value" tabindex="-1">Boolean Value <a class="header-anchor" href="#boolean-value" aria-label="Permalink to &quot;Boolean Value&quot;">​</a></h4><p>Determine whether Value 1 is true or false (Value 2 is not applicable here).</p><blockquote><p>Historical interface images are withheld pending review and recapture. Check operations against the current interface.</p></blockquote><h4 id="date-and-time" tabindex="-1">Date and Time <a class="header-anchor" href="#date-and-time" aria-label="Permalink to &quot;Date and Time&quot;">​</a></h4><p>Compare the relationship between Value 1 and Value 2 in terms of dates. You can compare strings in the format <code>yyyy-mm-dd hh:mm:ss</code> as well as Unix timestamp formats.</p><blockquote><p>Historical interface images are withheld pending review and recapture. Check operations against the current interface.</p></blockquote><h4 id="numeric" tabindex="-1">Numeric <a class="header-anchor" href="#numeric" aria-label="Permalink to &quot;Numeric&quot;">​</a></h4><p>Compare the relationship between Value 1 and Value 2 in terms of size, including:</p><ul><li>Greater than</li><li>Greater than or equal to</li><li>Less than</li><li>Less than or equal to</li><li>Equal to</li><li>Not equal to</li></ul><blockquote><p>Historical interface images are withheld pending review and recapture. Check operations against the current interface.</p></blockquote><h4 id="string" tabindex="-1">String <a class="header-anchor" href="#string" aria-label="Permalink to &quot;String&quot;">​</a></h4><p>Compare the relationship between Value 1 and Value 2 in terms of strings, including:</p><ul><li>Contains</li><li>Does not contain</li><li>Starts with...</li><li>Does not start with...</li><li>Ends with...</li><li>Does not end with...</li><li>Equal to</li><li>Not equal to</li></ul><blockquote><p>Historical interface images are withheld pending review and recapture. Check operations against the current interface.</p></blockquote><h2 id="output" tabindex="-1">Output <a class="header-anchor" href="#output" aria-label="Permalink to &quot;Output&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[true/false]</span></span></code></pre></div><blockquote><p>Historical interface images are withheld pending review and recapture. Check operations against the current interface.</p></blockquote>',28)])])}const m=a(o,[["render",r]]);export{h as __pageData,m as default};
